import 'dart:convert';
import 'package:flutter/material.dart';
import 'package:http/http.dart' as http;

const brand = Color(0xFFF5C542);
const apiUrl = String.fromEnvironment('API_URL', defaultValue: 'http://10.0.2.2:8000/api/v1');
void main() => runApp(const ElevraApp());

class ApiRepository {
  Future<List<Map<String, dynamic>>> list(String path) async { final response = await http.get(Uri.parse('$apiUrl/$path')).timeout(const Duration(seconds: 10)); if (response.statusCode != 200) throw Exception('Could not load content'); return List<Map<String,dynamic>>.from(jsonDecode(response.body)['items']); }
  Future<Map<String, dynamic>> get(String path, String slug) async { final response = await http.get(Uri.parse('$apiUrl/$path/$slug')).timeout(const Duration(seconds: 10)); if (response.statusCode != 200) throw Exception('Could not load this item'); return Map<String,dynamic>.from(jsonDecode(response.body)); }
}
class ElevraApp extends StatelessWidget { const ElevraApp({super.key}); @override Widget build(BuildContext context) => MaterialApp(title:'Elevra', theme:ThemeData(colorScheme:ColorScheme.fromSeed(seedColor:brand, brightness:Brightness.light), scaffoldBackgroundColor:const Color(0xFFFFFCF2), useMaterial3:true), home:const Shell()); }
class Shell extends StatefulWidget { const Shell({super.key}); @override State<Shell> createState()=>_ShellState(); }
class _ShellState extends State<Shell> { int tab=0; @override Widget build(BuildContext context) { final screens=[const Home(), const Explore(), const PlaceholderScreen(icon:Icons.bookmark_outline,title:'Saved',body:'Saving requires an Elevra account.'), const PlaceholderScreen(icon:Icons.notifications_none,title:'Notifications',body:'No notifications yet.'), const PlaceholderScreen(icon:Icons.person_outline,title:'Profile',body:'Sign in to personalize your Elevra experience.')]; return Scaffold(body:screens[tab], bottomNavigationBar:NavigationBar(selectedIndex:tab,onDestinationSelected:(v)=>setState(()=>tab=v),destinations:const[NavigationDestination(icon:Icon(Icons.home_outlined),label:'Home'),NavigationDestination(icon:Icon(Icons.explore_outlined),label:'Explore'),NavigationDestination(icon:Icon(Icons.bookmark_outline),label:'Saved'),NavigationDestination(icon:Icon(Icons.notifications_none),label:'Alerts'),NavigationDestination(icon:Icon(Icons.person_outline),label:'Profile')])); } }
class Home extends StatelessWidget { const Home({super.key}); @override Widget build(BuildContext c)=>SafeArea(child:ListView(padding:const EdgeInsets.all(20),children:[Text('ELEVRA',style:Theme.of(c).textTheme.labelLarge?.copyWith(color:Colors.amber.shade800,fontWeight:FontWeight.bold)),Text('Your Career &\nExam Companion',style:Theme.of(c).textTheme.headlineMedium?.copyWith(fontWeight:FontWeight.bold)),const SizedBox(height:12),const Text('Official information for the choices that shape your future.'),const SizedBox(height:28),const _LinkCard(title:'Upcoming exams',body:'Dates, eligibility, and official sources.',icon:Icons.school_outlined),const _LinkCard(title:'Latest opportunities',body:'Jobs, internships, scholarships and more.',icon:Icons.rocket_launch_outlined)])); }
class Explore extends StatelessWidget { const Explore({super.key}); @override Widget build(BuildContext c)=>DefaultTabController(length:2,child:Scaffold(appBar:AppBar(title:const Text('Explore'),bottom:const TabBar(tabs:[Tab(text:'Exams'),Tab(text:'Opportunities')])),body:const TabBarView(children:[ContentList(path:'exams',isExam:true),ContentList(path:'opportunities',isExam:false)]))); }
class ContentList extends StatefulWidget { final String path; final bool isExam; const ContentList({super.key,required this.path,required this.isExam}); @override State<ContentList> createState()=>_ContentListState(); }
class _ContentListState extends State<ContentList> { final repo=ApiRepository(); late Future<List<Map<String,dynamic>>> future; @override void initState(){super.initState();future=repo.list(widget.path);} Future<void> refresh() async=>setState(()=>future=repo.list(widget.path)); @override Widget build(BuildContext c)=>FutureBuilder(future:future,builder:(c,s){if(s.connectionState!=ConnectionState.done)return const Center(child:CircularProgressIndicator());if(s.hasError)return Center(child:Column(mainAxisSize:MainAxisSize.min,children:[Text('${s.error}'),FilledButton(onPressed:refresh,child:const Text('Try again'))]));final rows=s.data??[];if(rows.isEmpty)return const Center(child:Text('No results right now.'));return RefreshIndicator(onRefresh:refresh,child:ListView.builder(padding:const EdgeInsets.all(16),itemCount:rows.length,itemBuilder:(c,i){final x=rows[i];final title=widget.isExam?x['name']:x['title'];final sub=widget.isExam?x['conducting_body']:x['organization'];return Card(child:ListTile(title:Text(title??''),subtitle:Text('${sub??'To be announced'}\n${widget.isExam?x['category']:x['type']}'),isThreeLine:true,trailing:x['verified']==true?const Icon(Icons.verified,color:Colors.green):null,onTap:()=>Navigator.push(c,MaterialPageRoute(builder:(_)=>Detail(path:widget.path,slug:x['slug'],isExam:widget.isExam)))));}));}); }
class Detail extends StatefulWidget { final String path,slug; final bool isExam; const Detail({super.key,required this.path,required this.slug,required this.isExam}); @override State<Detail> createState()=>_DetailState(); }
class _DetailState extends State<Detail>{ late Future<Map<String,dynamic>> future; final repo=ApiRepository();@override void initState(){super.initState();future=repo.get(widget.path,widget.slug);}@override Widget build(BuildContext c)=>FutureBuilder(future:future,builder:(c,s){if(s.connectionState!=ConnectionState.done)return const Scaffold(body:Center(child:CircularProgressIndicator()));if(s.hasError)return Scaffold(appBar:AppBar(),body:Center(child:Text('${s.error}')));final x=s.data!;final title=widget.isExam?x['name']:x['title'];return Scaffold(appBar:AppBar(),body:ListView(padding:const EdgeInsets.all(20),children:[Text(title,style:Theme.of(c).textTheme.headlineSmall?.copyWith(fontWeight:FontWeight.bold)),const SizedBox(height:8),if(x['verified']==true)const Chip(label:Text('Verified source'),avatar:Icon(Icons.verified,color:Colors.green)),const SizedBox(height:20),Text('Overview',style:Theme.of(c).textTheme.titleLarge),Text(x['description']??'Details will be updated from the official source.'),const SizedBox(height:20),Text(widget.isExam?'Important dates':'Eligibility',style:Theme.of(c).textTheme.titleLarge),Text(widget.isExam?'Application deadline: ${x['application_deadline']??'To be announced'}\nExam date: ${x['exam_date']??'To be announced'}':x['eligibility']??'Eligibility details will be updated from the official source.'),const SizedBox(height:24),FilledButton(onPressed:()=>ScaffoldMessenger.of(c).showSnackBar(const SnackBar(content:Text('Open the official source in your browser.'))),child:Text(widget.isExam?'Visit official website':'Apply on official website'))]));});}
class PlaceholderScreen extends StatelessWidget { final IconData icon; final String title,body; const PlaceholderScreen({super.key,required this.icon,required this.title,required this.body}); @override Widget build(BuildContext c)=>SafeArea(child:Center(child:Padding(padding:const EdgeInsets.all(30),child:Column(mainAxisSize:MainAxisSize.min,children:[Icon(icon,size:48),const SizedBox(height:16),Text(title,style:Theme.of(c).textTheme.headlineSmall),const SizedBox(height:8),Text(body,textAlign:TextAlign.center)])))); }
class _LinkCard extends StatelessWidget { final String title,body; final IconData icon; const _LinkCard({required this.title,required this.body,required this.icon}); @override Widget build(BuildContext c)=>Card(child:ListTile(contentPadding:const EdgeInsets.all(18),leading:Icon(icon,color:Colors.amber.shade800),title:Text(title,style:const TextStyle(fontWeight:FontWeight.bold)),subtitle:Text(body))); }
